2633	/*--------------------------------------
2634	 * recurring theme: advance to first 6k+1 candidate, checking + possibly
2635	 * registering initial state (which must have been 6k+5 if it has been
2636	 * rechecked)
2637	 *
2638	 * possibly updates both 'ps' and 'adv'
2639	 */
2640	static inline
2641	unsigned long plain_advance_to_6kp1(uint64_t *lsb, unsigned long count,
2642	                          struct PP_Mod16bit *ps,
2643		                 struct SIMD_Advance *adv)
2644	{
2645		static unsigned long rv = 0;
2646	
2647		if (ps && adv && (ps->mod6 == 5)) {         // advance 6k+5 -> 6(k+1)+1
2648			adv->wr = simd_check_plain1(lsb, count, adv->wr,
2649			                            adv->tmp, adv->tm2, ps);
2650	
2651			simd_advance_all(ps, 2);
2652			rv = adv->wr;
2653		}
2654	
2655		return rv;
2656	}
