2659	#if defined(NO_SIMDDIVIDE_M) && defined(NO_SIMDDIVIDE_L)  //-----------------
2660	//--------------------------------------
2661	static
2662	uint64_t plain_advance_s(uint64_t *lsb, unsigned long count,
2663	               struct PP_Mod16bit *dst,
2664	         const struct PP_Mod16bit *src)
2665	{
2666		struct SIMD_Advance adv = SIMD_ADVANCE_INIT0;
2667	
2668		count = init_search(lsb, count, dst, src, 0);
2669		if (!count)
2670			return 0;
2671	
2672		adv.wr = plain_advance_to_6kp1(lsb, count, dst, &adv);
2673	
2674		while (adv.wr < count) {                // invariant: candidate is 6k+1
2675			adv.wr = simd_check_plain1(lsb, count, adv.wr,
2676			                           adv.tmp, adv.tm2, dst);
2677	
2678			if (adv.wr < count) {
