2682				                           adv.tmp, adv.tm2, dst);
2683				if (adv.wr < count)
2684					simd_advance_all(dst, 2);   // 6k+5 -> 6(k+1)+1
2685			}
2686		}
2687	
2688		wipe_advance_struct(&adv);
2689	
2690		return dst->lsb;
2691	}
