726	/*-----------------------------------------
727	 * v[] += adv; preserving mod-prime by subtracting m2r[] if applicable
728	 */
729	static inline
730	REALLY_FORCE_INLINE
731	/**/
732	void simd_advance64x16_m2r_inpl(uint16_t v[static 64], uint16_t adv,
733	                        const uint16_t m2r[static 64])
734	{
735		simd_advance16x16_inpl(  v,          adv       );
736		simd_m2range16x16_inpl(  v,          m2r       );
737	
738		simd_advance16x16_inpl(&(v[ 16 ]),   adv       );
739		simd_m2range16x16_inpl(&(v[ 16 ]), &(m2r[ 16 ]));
740	
741		simd_advance16x16_inpl(&(v[ 32 ]),   adv       );
742		simd_m2range16x16_inpl(&(v[ 32 ]), &(m2r[ 32 ]));
743	
744		simd_advance16x16_inpl(&(v[ 48 ]),   adv       );
745		simd_m2range16x16_inpl(&(v[ 48 ]), &(m2r[ 48 ]));
746	}
